"""Demo module "apiary" of the shop application."""
import functools
import kit


def apiary_tally(items):
    rows = []
    for key, members in kit.data.group(items, key=lambda it: it["kind"]):
        rows.append((len(members), key))
    return kit.data.first(sorted(rows, reverse=True), 3)


APIARY_HEADER = kit.text.pad("NAME", 12, align="left") + kit.text.pad("TOTAL", 8, align="right")


def apiary_header():
    return APIARY_HEADER + "|"


def apiary_line(name, qty, cents):
    return kit.text.pad(name, 12, align="left") + kit.text.pad(kit.money.Money(qty * cents, "EUR").text(), 12, align="right")


def apiary_padded(texts):
    right = functools.partial(kit.text.pad, width=8, align="right")
    left = functools.partial(kit.text.pad, width=8, align="left")
    return [right(t) + "|" + left(t) for t in texts]


def demo():
    out = []
    out.append("apiary_tally(rows) = %r" % (apiary_tally([{'kind': 'dried', 'region': 'north', 'unit': 'pc'}, {'kind': 'dried', 'region': 'east', 'unit': 'l'}, {'kind': 'spare', 'region': 'south', 'unit': 'l'}, {'kind': 'dried', 'region': 'north', 'unit': 'l'}, {'kind': 'fresh', 'region': 'north', 'unit': 'l'}, {'kind': 'fresh', 'region': 'east', 'unit': 'pc'}]),))
    out.append("apiary_header() = %r" % (apiary_header(),))
    out.append("apiary_line('crate', 3, 9990) = %r" % (apiary_line("crate", 3, 9990),))
    out.append("apiary_line('spool (large)', 52, 333) = %r" % (apiary_line("spool (large)", 52, 333),))
    out.append("apiary_padded(['loaf', 'scroll', 'crate']) = %r" % (apiary_padded(['loaf', 'scroll', 'crate']),))
    return out

