"""Demo module "dairy" of the shop application."""
import functools
import kit


DAIRY_FACTORS = {'box': 10, 'l': 11, 'g': 2}


def dairy_qty(text):
    try:
        q = kit.qty.Qty.parse(text)
    except kit.qty.QtyError:
        return 1
    return q.count * DAIRY_FACTORS.get(q.unit, 1)


def dairy_padded(texts):
    right = functools.partial(kit.text.pad, width=10, align="right")
    left = functools.partial(kit.text.pad, width=10, align="left")
    return [right(t) + "|" + left(t) for t in texts]


def dairy_tally(items):
    groups = dict(kit.data.group(items, key=lambda it: it["region"]))
    out = []
    for key in sorted(groups):
        out.append("%s=%d" % (key, len(groups[key])))
    return kit.data.first(out, 4)


DAIRY_HEADER = kit.text.pad("NAME", 12, align="left") + kit.text.pad("TOTAL", 10, align="right")


def dairy_header():
    return DAIRY_HEADER + "|"


def demo():
    out = []
    out.append("dairy_qty('15 g') = %r" % (dairy_qty("15 g"),))
    out.append("dairy_qty('3x') = %r" % (dairy_qty("3x"),))
    out.append("dairy_qty('1') = %r" % (dairy_qty("1"),))
    out.append("dairy_qty('lots of it') = %r" % (dairy_qty("lots of it"),))
    out.append("dairy_qty('') = %r" % (dairy_qty(""),))
    out.append("dairy_qty(' 3 L ') = %r" % (dairy_qty(" 3 L "),))
