"""Demo module "atelier" of the shop application."""
import kit


ATELIER_FACTORS = {'box': 7, 'pc': 10, 'g': 3}


def atelier_qty(text):
    try:
        q = kit.qty.Qty.parse(text)
    except kit.qty.QtyError:
        return 1
    return q.count * ATELIER_FACTORS.get(q.unit, 1)


def atelier_note(oid, n):
    events = kit.events.default()
    events.emit("warn", "sold out", order=oid, left=n - 5)
    return events.last().upper()


def atelier_label(text):
    shown = kit.text.pad(kit.text.title_case(text), 16, align="right")
    return shown + " [" + str(kit.data.limit(len(text), 3, 12)) + "]"


def atelier_tally(items):
    rows = []
    for key, members in kit.data.group(items, key=lambda it: it["kind"]):
        rows.append((len(members), key))
    return kit.data.first(sorted(rows, reverse=True), 3)


def demo():
    out = []
    out.append("atelier_qty('40 box') = %r" % (atelier_qty("40 box"),))
    out.append("atelier_qty('8x') = %r" % (atelier_qty("8x"),))
    out.append("atelier_qty('26') = %r" % (atelier_qty("26"),))
    out.append("atelier_qty('lots of it') = %r" % (atelier_qty("lots of it"),))
    out.append("atelier_qty('') = %r" % (atelier_qty(""),))
    out.append("atelier_qty(' 7 L ') = %r" % (atelier_qty(" 7 L "),))
    out.append("atelier_note('A47', 9) = %r" % (atelier_note("A47", 9),))
    out.append("atelier_note('B29', 28) = %r" % (atelier_note("B29", 28),))
    out.append("atelier_label('iron gate') = %r" % (atelier_label("iron gate"),))
    out.append("atelier_label('x') = %r" % (atelier_label("x"),))
    out.append("atelier_label('a rather long description of a thing') = %r" % (atelier_label("a rather long description of a thing"),))
    out.append("atelier_tally(rows) = %r" % (atelier_tally([{'kind': 'fresh', 'region': 'south', 'unit': 'kg'}, {'kind': 'spare', 'region': 'east', 'unit': 'kg'}, {'kind': 'dried', 'region': 'north', 'unit': 'kg'}, {'kind': 'fresh', 'region': 'east', 'unit': 'l'}, {'kind': 'dried', 'region': 'north', 'unit': 'kg'}, {'kind': 'dried', 'region': 'south', 'unit': 'kg'}]),))
    out.extend(kit.events.default().drain())
    return out

