"""Demo module "fishery" of the shop application."""
import kit


def fishery_labels(names):
    return list(map(kit.text.title_case, names))


def fishery_tally(items):
    buckets = dict(kit.data.group(items, key=lambda it: it["unit"]))
    first_seen = list(buckets)
    return first_seen, {k: len(v) for k, v in sorted(buckets.items())}


