"""Demo module "atelier" of the shop application."""
import oldkit as ok


ATELIER_FACTORS = {'box': 7, 'pc': 10, 'g': 3}


def atelier_qty(text):
    parsed = ok.parse_qty(text)
    if parsed is None:
        return 1
    count, unit = parsed
    return count * ATELIER_FACTORS.get(unit, 1)


def atelier_note(oid, n):
    line = ok.log("warn", "sold out", order=oid, left=n - 5)
    return line.upper()


def atelier_label(text):
    shown = ok.pad_left(ok.title(text), 16)
    return shown + " [" + str(ok.clamp(len(text), 3, 12)) + "]"


def atelier_tally(items):
    rows = []
    for key, members in ok.group_by(items, lambda it: it["kind"]).items():
        rows.append((len(members), key))
    return ok.take(sorted(rows, reverse=True), 3)


def demo():
    out = []
    out.append("atelier_qty('40 box') = %r" % (atelier_qty("40 box"),))
