"""Demo module "chandlery" of the shop application."""
import functools
import kit


CHANDLERY_FACTORS = {'l': 4, 'g': 10, 'm': 10}


def chandlery_qty(text):
    try:
        q = kit.qty.Qty.parse(text)
    except kit.qty.QtyError:
        return 0
    return q.count * CHANDLERY_FACTORS.get(q.unit, 1)


def chandlery_tally(items):
    rows = []
    for key, members in kit.data.group(items, key=lambda it: it["unit"]):
        rows.append((len(members), key))
    return kit.data.first(sorted(rows, reverse=True), 3)


def chandlery_capped(deltas):
    return functools.reduce(lambda acc, x: kit.data.limit(acc + x, -10, 40), deltas, 0)


CHANDLERY_RATES = {'rates': {'south': {'dried': 43, 'loose': 21, 'fresh': 45}, 'east': {'sealed': 14, 'fresh': 55, 'loose': 26}, 'coast': {'fresh': 52, 'dried': 46, 'loose': 58}}}


def chandlery_rate(region, kind):
    by_kind = kit.data.dig(CHANDLERY_RATES, ("rates", region), default={})
    return by_kind.get(kind, -1) + kit.data.dig(CHANDLERY_RATES, ("rates", "nowhere"), default=0)


def chandlery_note(oid, n):
    kit.events.default().emit("info", "checked", order=oid, count=n)
    return n * 3


def demo():
    out = []
    out.append("chandlery_qty('33 m') = %r" % (chandlery_qty("33 m"),))
    out.append("chandlery_qty('7x') = %r" % (chandlery_qty("7x"),))
    out.append("chandlery_qty('1') = %r" % (chandlery_qty("1"),))
    out.append("chandlery_qty('lots of it') = %r" % (chandlery_qty("lots of it"),))
    out.append("chandlery_qty('') = %r" % (chandlery_qty(""),))
    out.append("chandlery_qty(' 6 L ') = %r" % (chandlery_qty(" 6 L "),))
    out.append("chandlery_tally(rows) = %r" % (chandlery_tally([{'kind': 'fresh', 'region': 'north', 'unit': 'kg'}, {'kind': 'spare', 'region': 'east', 'unit': 'pc'}, {'kind': 'spare', 'region': 'south', 'unit': 'kg'}, {'kind': 'spare', 'region': 'south', 'unit': 'l'}, {'kind': 'dried', 'region': 'north', 'unit': 'l'}, {'kind': 'spare', 'region': 'south', 'unit': 'pc'}, {'kind': 'fresh', 'region': 'south', 'unit': 'l'}]),))
    out.append("chandlery_capped([-29, 46, 54, 55, 3, 55]) = %r" % (chandlery_capped([-29, 46, 54, 55, 3, 55]),))
    out.append("chandlery_rate('south', 'dried') = %r" % (chandlery_rate("south", "dried"),))
    out.append("chandlery_rate('east', 'sealed') = %r" % (chandlery_rate("east", "sealed"),))
    out.append("chandlery_rate('atlantis', 'dried') = %r" % (chandlery_rate("atlantis", "dried"),))
    out.append("chandlery_note('A46', 17) = %r" % (chandlery_note("A46", 17),))
    out.append("chandlery_note('B59', 20) = %r" % (chandlery_note("B59", 20),))
    out.extend(kit.events.default().drain())
    return out

