"""Event lines."""


class Events:
    def __init__(self):
        self._lines = []

    def emit(self, level, msg, **ctx):
        """Record `{LEVEL} msg key=value ...` (keys sorted).  Returns nothing: see last()."""
        self._lines.append("{%s} %s" % (level.upper(), msg) + "".join(" %s=%s" % (k, ctx[k]) for k in sorted(ctx)))

    def last(self):
        return self._lines[-1]

    def drain(self):
        out = list(self._lines)
        del self._lines[:]
        return out


_DEFAULT = Events()


def default():
    """The process-wide Events instance."""
    return _DEFAULT

