start.kit/qty.py:
"""Quantities such as '12 kg'."""
import re

_QTY = re.compile(r"^\s*([0-9]+)\s*([A-Za-z]*)\s*$")


class QtyError(ValueError):
    pass


class Qty:
    def __init__(self, count, unit):
        self.count = count
        self.unit = unit

    @classmethod
    def parse(cls, text):
        """Qty for '12 kg', '3x' or '7' (unit defaults to 'ea'); raises QtyError otherwise."""
        m = _QTY.match(text)
        if not m:
            raise QtyError("not a quantity: %r" % (text,))
        return cls(int(m.group(1)), m.group(2) or "ea")

    @classmethod
    def try_parse(cls, text):
        """Like parse, but returns None instead of raising."""
        try:
            return cls.parse(text)
        except QtyError:
            return None

