"""oldkit: the helper module this codebase has used so far.  It is being retired: see README.md."""
import re

_LOG = []
_QTY = re.compile(r"^\s*([0-9]+)\s*([A-Za-z]*)\s*$")


def fmt_amount(cents, cur="CHF"):
    """12.50 EUR style text for an integer number of cents."""
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(cents), 100)
    return "%s%d.%02d %s" % (sign, whole, frac, cur)


def parse_qty(text):
    """(count, unit) for texts like '12 kg', '3x' or '7' (unit defaults to 'ea'); None when the text is not a quantity."""
    m = _QTY.match(text)
    if not m:
        return None
    return int(m.group(1)), (m.group(2) or "ea")


def pad_right(s, width):
    """Pad on the right (the text stays at the left)."""
    return s.ljust(width)


def pad_left(s, width):
    """Pad on the left (the text moves to the right)."""
    return s.rjust(width)


def title(s):
    return " ".join(w.capitalize() for w in s.split())


def sort_key(s):
    return (s.lower(), s)


def pick(d, *keys, default=None):
    """Nested dictionary lookup: pick(cfg, "a", "b") is cfg["a"]["b"], or `default` when a key is missing."""
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur


def take(seq, n):
    return list(seq)[:n]


def group_by(items, keyfn):
    """dict: key -> list of items, keys in order of first appearance."""
    out = {}
    for it in items:
        out.setdefault(keyfn(it), []).append(it)
    return out


def log(level, msg, **ctx):
    """Append a line to the global log and return it: `{LEVEL} msg key=value ...` with the keys sorted."""
    line = "{%s} %s" % (level.upper(), msg) + "".join(" %s=%s" % (k, ctx[k]) for k in sorted(ctx))
    _LOG.append(line)
    return line


def flush_log():
    out = list(_LOG)
    del _LOG[:]
    return out


def clamp(x, lo, hi):
    return max(lo, min(hi, x))

start.tests/run_examples.py:
#!/usr/bin/env python3
"""Example checks: python3 tests/run_examples.py [-v] [group-or-name-fragment]  (builds the program first)"""
import concurrent.futures as cf
import json
import os
import re
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CASES = os.path.join(ROOT, "tests", "examples.json")
BUILD = ""
RUN = [(ROOT + "/" + p[2:]) if p.startswith("@/") else p for p in ["python3", "@/run.py"]]
TIMEOUT = 30
WORKERS = 3


def build():
    if not BUILD:
        return True
    r = subprocess.run(["bash", "-c", BUILD], cwd=ROOT, capture_output=True, text=True)
    if r.returncode != 0:
        print("BUILD FAILED")
        print((r.stdout + r.stderr)[-3000:])
        return False
    return True


def execute(c):
    if c.get("static"):
        fp = os.path.join(ROOT, c["static"]["path"])
        text = open(fp, encoding="utf-8", errors="replace").read() if os.path.isfile(fp) else ""
        hits = sorted(set(re.findall(c["static"]["forbid"], text)))[:3]
        need = c["static"].get("require")
        return {"stdout": "", "code": 0, "files": {}, "stderr": "", "hits": hits, "missing": bool(need and not re.search(need, text))}
    d = tempfile.mkdtemp(prefix="chk-")
    try:
        for p, t in sorted(c.get("files", {}).items()):
            fp = os.path.join(d, p)
            os.makedirs(os.path.dirname(fp), exist_ok=True)
            with open(fp, "w", encoding="utf-8", newline="") as f:
                f.write(t)
        try:
            r = subprocess.run(RUN + list(c.get("args", [])), input=c.get("stdin", "").encode(), cwd=d, capture_output=True, timeout=TIMEOUT)
            out = r.stdout.decode("utf-8", "replace").replace("\r\n", "\n")
            err = r.stderr.decode("utf-8", "replace")
            code = r.returncode
        except subprocess.TimeoutExpired:
            out, err, code = "", "timed out after %d s" % TIMEOUT, 124
        files = {}
        for p in c.get("watch", []) or list((c.get("out_files") or {}).keys()):
            fp = os.path.join(d, p)
            files[p] = open(fp, encoding="utf-8", newline="").read() if os.path.isfile(fp) else None
        return {"stdout": out, "code": code, "files": files, "stderr": err[-600:]}
    finally:
        import shutil
        shutil.rmtree(d, ignore_errors=True)


def first_diff(got, want):
    g, w = got.split("\n"), want.split("\n")
    for i in range(max(len(g), len(w))):
        a = g[i] if i < len(g) else "<missing>"
        b = w[i] if i < len(w) else "<missing>"
        if a != b:
            return "line %d:\n      got:  %s\n      want: %s" % (i + 1, a[:200], b[:200])
    return "(no difference found)"


def judge(c, res):
    why = []
    if c.get("static"):
        if res["hits"]:
            why.append("%s still contains %s" % (c["static"]["path"], ", ".join(repr(h) for h in res["hits"])))
        if res.get("missing"):
            why.append("%s does not use the new API" % c["static"]["path"])
        return why
    if res["stdout"].rstrip("\n") != c["stdout"].rstrip("\n"):
        why.append("stdout differs at " + first_diff(res["stdout"].rstrip("\n"), c["stdout"].rstrip("\n")))
    if res["code"] != c.get("code", 0):
        why.append("exit code %s, expected %s" % (res["code"], c.get("code", 0)))
        if res["stderr"].strip():
            why.append("stderr: " + res["stderr"].strip().replace("\n", " | ")[-300:])
    for p, want in sorted((c.get("out_files") or {}).items()):
        got = res["files"].get(p)
        if got != want:
            if want is None:
                why.append("file %s should not exist" % p)
            elif got is None:
                why.append("file %s was not written" % p)
            else:
                why.append("file %s differs at " % p + first_diff(got.rstrip("\n"), want.rstrip("\n")))
    return why


def main(argv):
    cases = json.load(open(CASES, encoding="utf-8"))
    if "--record" in argv:
        out = argv[argv.index("--record") + 1]
        if not build():
            return 3
        with cf.ThreadPoolExecutor(max_workers=WORKERS) as ex:
            results = list(ex.map(execute, cases))
        with open(out, "w", encoding="utf-8") as f:
            json.dump(results, f)
        return 0
    verbose = "-v" in argv
    pick = [a for a in argv if not a.startswith("-")]
    if pick:
        cases = [c for c in cases if any(s in c["name"] or s == c["group"] for s in pick)]
    if not build():
        print(json.dumps({"score": 0.0}))
        return 1
    with cf.ThreadPoolExecutor(max_workers=WORKERS) as ex:
        results = list(ex.map(execute, cases))
    groups = {}
    shown = 0
    for c, res in zip(cases, results):
        why = judge(c, res)
        groups.setdefault(c["group"], []).append(not why)
        if why and (verbose or shown < 6):
            shown += 1
            print("FAIL [%s] %s" % (c["group"], c["name"]))
            if c.get("args"):
                print("    args: " + " ".join(c["args"]))
            for w in why:
                print("    " + w)
    total = sum(len(v) for v in groups.values())
