"""Demo module "apiary" of the shop application."""
import kit


APIARY_FACTORS = {'box': 8, 'pc': 2, 'g': 2}


def apiary_qty(text):
    try:
        q = kit.qty.Qty.parse(text)
    except kit.qty.QtyError:
        return -1
    return q.count * APIARY_FACTORS.get(q.unit, 1)


APIARY_HEADER = kit.text.pad("NAME", 12, align="left") + kit.text.pad("TOTAL", 10, align="right")


def apiary_header():
    return APIARY_HEADER + "|"


def apiary_tally(items):
    buckets = dict(kit.data.group(items, key=lambda it: it["region"]))
    first_seen = list(buckets)
    return first_seen, {k: len(v) for k, v in sorted(buckets.items())}


def _apiary_event(msg, **ctx):
    events = kit.events.default()
    events.emit("debug", msg, **ctx)
    return events.last()


def apiary_note(oid, n):
    _apiary_event("inspected", order=oid, n=n)
    return n + 4


def demo():
    out = []
    out.append("apiary_qty('20 pc') = %r" % (apiary_qty("20 pc"),))
    out.append("apiary_qty('6x') = %r" % (apiary_qty("6x"),))
    out.append("apiary_qty('4') = %r" % (apiary_qty("4"),))
    out.append("apiary_qty('lots of it') = %r" % (apiary_qty("lots of it"),))
    out.append("apiary_qty('') = %r" % (apiary_qty(""),))
    out.append("apiary_qty(' 5 L ') = %r" % (apiary_qty(" 5 L "),))
    out.append("apiary_header() = %r" % (apiary_header(),))
    out.append("apiary_tally(rows) = %r" % (apiary_tally([{'kind': 'fresh', 'region': 'north', 'unit': 'kg'}, {'kind': 'dried', 'region': 'east', 'unit': 'kg'}, {'kind': 'spare', 'region': 'north', 'unit': 'l'}, {'kind': 'dried', 'region': 'south', 'unit': 'pc'}, {'kind': 'spare', 'region': 'south', 'unit': 'pc'}, {'kind': 'fresh', 'region': 'east', 'unit': 'pc'}, {'kind': 'spare', 'region': 'north', 'unit': 'kg'}]),))
    out.append("apiary_note('A26', 17) = %r" % (apiary_note("A26", 17),))
    out.append("apiary_note('B97', 23) = %r" % (apiary_note("B97", 23),))
    out.extend(kit.events.default().drain())
    return out

