"""Demo module "bakery" of the shop application."""
import kit


def _bakery_event(msg, **ctx):
    events = kit.events.default()
    events.emit("debug", msg, **ctx)
    return events.last()


def bakery_note(oid, n):
    _bakery_event("restocked", order=oid, n=n)
    return n + 3


BAKERY_FACTORS = {'g': 6, 'kg': 5, 'pc': 11}


def bakery_qty(text):
    try:
        q = kit.qty.Qty.parse(text)
    except kit.qty.QtyError:
        return 0
    return q.count * BAKERY_FACTORS.get(q.unit, 1)


def bakery_names(names):
    return kit.data.first(sorted(names, key=kit.text.sort_key), 3)


def bakery_tally(items):
    groups = dict(kit.data.group(items, key=lambda it: it["unit"]))
