start.kit/data.py:
"""Small data helpers."""


def dig(d, path, default=None):
    """Nested lookup along a tuple of keys; `default` when a key is missing."""
    cur = d
    for k in path:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur


def first(seq, n):
    return list(seq)[:n]


def group(items, key):
    """List of (key, [items]) pairs in order of first appearance of the keys."""
    order, buckets = [], {}
    for it in items:
        k = key(it)
        if k not in buckets:
            buckets[k] = []
            order.append(k)
        buckets[k].append(it)
    return [(k, buckets[k]) for k in order]


def limit(x, lo, hi):
    return max(lo, min(hi, x))

start.kit/events.py:
"""Event lines."""


class Events:
    def __init__(self):
        self._lines = []

    def emit(self, level, msg, **ctx):
        """Record `(LEVEL) msg key=value ...` (keys sorted).  Returns nothing: see last()."""
        self._lines.append("(%s) %s" % (level.upper(), msg) + "".join(" %s=%s" % (k, ctx[k]) for k in sorted(ctx)))

    def last(self):
        return self._lines[-1]

    def drain(self):
        out = list(self._lines)
        del self._lines[:]
        return out


_DEFAULT = Events()


def default():
    """The process-wide Events instance."""
    return _DEFAULT

start.kit/money.py:
"""Money values."""


class Money:
    """An amount in cents of a currency; both are required."""

    def __init__(self, cents, cur):
        self.cents = cents
        self.cur = cur

    def text(self):
        sign = "-" if self.cents < 0 else ""
        whole, frac = divmod(abs(self.cents), 100)
        return "%s%d.%02d %s" % (sign, whole, frac, self.cur)

start.kit/qty.py:
"""Quantities such as '12 kg'."""
import re

_QTY = re.compile(r"^\s*([0-9]+)\s*([A-Za-z]*)\s*$")


class QtyError(ValueError):
    pass


class Qty:
    def __init__(self, count, unit):
        self.count = count
        self.unit = unit

    @classmethod
    def parse(cls, text):
        """Qty for '12 kg', '3x' or '7' (unit defaults to 'unit'); raises QtyError otherwise."""
        m = _QTY.match(text)
        if not m:
            raise QtyError("not a quantity: %r" % (text,))
        return cls(int(m.group(1)), m.group(2) or "unit")

    @classmethod
    def try_parse(cls, text):
        """Like parse, but returns None instead of raising."""
        try:
            return cls.parse(text)
        except QtyError:
            return None

