"""oldkit: the helper module this codebase has used so far.  It is being retired: see README.md."""
import re

_LOG = []
_QTY = re.compile(r"^\s*([0-9]+)\s*([A-Za-z]*)\s*$")


def fmt_amount(cents, cur="CHF"):
    """12.50 EUR style text for an integer number of cents."""
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(cents), 100)
    return "%s%d.%02d %s" % (sign, whole, frac, cur)


def parse_qty(text):
    """(count, unit) for texts like '12 kg', '3x' or '7' (unit defaults to 'pc'); None when the text is not a quantity."""
    m = _QTY.match(text)
    if not m:
        return None
    return int(m.group(1)), (m.group(2) or "pc")


def pad_right(s, width):
    """Pad on the right (the text stays at the left)."""
    return s.ljust(width)


def pad_left(s, width):
    """Pad on the left (the text moves to the right)."""
    return s.rjust(width)


def title(s):
    words = s.split()
    return " ".join(words[:1] + [w.lower() for w in words[1:]]).capitalize() if words else ""


def sort_key(s):
    return (s.lower(), s)


def pick(d, *keys, default=None):
    """Nested dictionary lookup: pick(cfg, "a", "b") is cfg["a"]["b"], or `default` when a key is missing."""
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur


def take(seq, n):
    return list(seq)[:n]


def group_by(items, keyfn):
    """dict: key -> list of items, keys in order of first appearance."""
    out = {}
    for it in items:
        out.setdefault(keyfn(it), []).append(it)
    return out


def log(level, msg, **ctx):
    """Append a line to the global log and return it: `[LEVEL] msg key=value ...` with the keys sorted."""
    line = "[%s] %s" % (level.upper(), msg) + "".join(" %s=%s" % (k, ctx[k]) for k in sorted(ctx))
    _LOG.append(line)
    return line


def flush_log():
    out = list(_LOG)
    del _LOG[:]
    return out


def clamp(x, lo, hi):
    return max(lo, min(hi, x))

